{"op":"add","path":"/root","value":"onboarding-wizard"}
{"op":"add","path":"/elements/main-layout","value":{"type":"Stack","props":{"direction":"vertical","gap":"lg"},"children":["header","progress","step-1","step-2","step-3","navigation"]}}
{"op":"add","path":"/elements/header","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm"},"children":["heading-title","heading-subtitle"]}}
{"op":"add","path":"/elements/heading-title","value":{"type":"Heading","props":{"text":"Welcome!","level":"h1"},"children":[]}}
{"op":"add","path":"/elements/heading-subtitle","value":{"type":"Text","props":{"text":"Let's get you set up in a few quick steps.","variant":"lead"},"children":[]}}
{"op":"add","path":"/elements/progress","value":{"type":"Progress","props":{"label":"Setup progress","value":{"$cond":{"$state":"/currentStep","eq":1},"$then":33,"$else":{"$cond":{"$state":"/currentStep","eq":2},"$then":66,"$else":100}}},"children":[]}}
{"op":"add","path":"/elements/step-1","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"visible":{"$state":"/currentStep","eq":1},"children":["step-1-card"]}}
{"op":"add","path":"/elements/step-1-card","value":{"type":"Card","props":{"title":"Create your account"},"children":["name-input","email-input","password-input"]}}
{"op":"add","path":"/elements/name-input","value":{"type":"Input","props":{"label":"Full Name","value":{"$bindState":"/formData/fullName"}},"children":[]}}
{"op":"add","path":"/elements/email-input","value":{"type":"Input","props":{"label":"Email Address","type":"email","value":{"$bindState":"/formData/email"}},"children":[]}}
{"op":"add","path":"/elements/password-input","value":{"type":"Input","props":{"label":"Password","type":"password","value":{"$bindState":"/formData/password"}},"children":[]}}
{"op":"add","path":"/elements/step-2","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"visible":{"$state":"/currentStep","eq":2},"children":["step-2-card"]}}
{"op":"add","path":"/elements/step-2-card","value":{"type":"Card","props":{"title":"Preferences"},"children":["notifications-switch","theme-radio","newsletter-select"]}}
{"op":"add","path":"/elements/notifications-switch","value":{"type":"Switch","props":{"label":"Enable email notifications","checked":{"$bindState":"/formData/notifications"}},"children":[]}}
{"op":"add","path":"/elements/theme-radio","value":{"type":"RadioGroup","props":{"label":"Color Theme","options":["Light","Dark","System"],"value":{"$bindState":"/formData/theme"}},"children":[]}}
{"op":"add","path":"/elements/newsletter-select","value":{"type":"Select","props":{"label":"Newsletter Frequency","options":["Daily","Weekly","Monthly","Never"],"value":{"$bindState":"/formData/newsletter"}},"children":[]}}
{"op":"add","path":"/elements/step-3","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"visible":{"$state":"/currentStep","eq":3},"children":["step-3-card","summary-stats"]}}
{"op":"add","path":"/elements/step-3-card","value":{"type":"Card","props":{"title":"You're all set!"},"children":["welcome-avatar","welcome-text-1","welcome-text-2"]}}
{"op":"add","path":"/elements/welcome-avatar","value":{"type":"Avatar","props":{"name":{"$cond":{"$state":"/formData/fullName","not":true},"$then":"User","$else":{"$state":"/formData/fullName"}},"size":"lg"},"children":[]}}
{"op":"add","path":"/elements/welcome-text-1","value":{"type":"Text","props":{"text":"Your account is ready to go."},"children":[]}}
{"op":"add","path":"/elements/welcome-text-2","value":{"type":"Text","props":{"text":{"$template":"We've sent a confirmation email to ${/formData/email}."},"variant":"muted"},"children":[]}}
{"op":"add","path":"/elements/summary-stats","value":{"type":"Stack","props":{"direction":"horizontal","gap":"md","align":"start"},"children":["stat-name","stat-theme"]}}
{"op":"add","path":"/elements/stat-name","value":{"type":"Stat","props":{"label":"Name","value":{"$state":"/formData/fullName"}},"children":[]}}
{"op":"add","path":"/elements/stat-theme","value":{"type":"Stat","props":{"label":"Theme","value":{"$state":"/formData/theme"}},"children":[]}}
{"op":"add","path":"/elements/navigation","value":{"type":"Stack","props":{"direction":"horizontal","gap":"md","align":"end"},"children":["back-button","next-button","finish-button"]}}
{"op":"add","path":"/elements/back-button","value":{"type":"Button","props":{"label":"Back","variant":"secondary"},"visible":{"$state":"/currentStep","gt":1},"on":{"press":{"action":"setState","params":{"statePath":"/currentStep","value":{"$cond":{"$state":"/currentStep","eq":3},"$then":2,"$else":1}}}}},"children":[]}}
{"op":"add","path":"/elements/next-button","value":{"type":"Button","props":{"label":"Next"},"visible":{"$state":"/currentStep","lt":3},"on":{"press":{"action":"setState","params":{"statePath":"/currentStep","value":{"$cond":{"$state":"/currentStep","eq":1},"$then":2,"$else":3}}}}},"children":[]}}
{"op":"add","path":"/elements/finish-button","value":{"type":"Button","props":{"label":"Finish","variant":"default"},"visible":{"$state":"/currentStep","eq":3},"on":{"press":{"action":"setState","params":{"statePath":"/submitted","value":true}}},"children":[]}}
{"op":"add","path":"/state/currentStep","value":1}
{"op":"add","path":"/state/formData/fullName","value":""}
{"op":"add","path":"/state/formData/email","value":""}
{"op":"add","path":"/state/formData/password","value":""}
{"op":"add","path":"/state/formData/notifications","value":true}
{"op":"add","path":"/state/formData/theme","value":"Light"}
{"op":"add","path":"/state/formData/newsletter","value":"Weekly"}
{"op":"add","path":"/state/submitted","value":false}
